fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // k is 1-based, and we require 1 <= k < list.len()
    assert!(k >= 1 && k < list.len(), "k must satisfy 1 <= k < list.len()");
    let remove_idx = k - 1; // convert to 0-based index

    let mut new_list = Vec::with_capacity(list.len() - 1);
    for (i, &value) in list.iter().enumerate() {
        if i != remove_idx {
            new_list.push(value);
        }
    }
    new_list
}

